"""Report agreed tension-only scope, the selected rule and computed fixtures."""
import csv,html,json
from pathlib import Path
import numpy as np
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'results/tension_reference'

def main():
    cfg=json.loads((ROOT/'scenarios/tension_reference.json').read_text(encoding='utf-8'));rows=[];manifest={}
    for task in ['jump','ohp']:
        folder=OUT/task;summary=json.loads((folder/'summary.json').read_text(encoding='utf-8'));manifest[task]=summary
        with (folder/'muscle_tensions.csv').open('w',newline='',encoding='utf-8') as handle:
            writer=csv.writer(handle);writer.writerow(['task','profile','time_s','muscle_element','total_tension_N','active_tension_N','passive_tension_N','status'])
            for profile,checks in summary['profiles'].items():
                data=dict(np.load(folder/(profile+'.npz')))
                for i,t in enumerate(data['times']):
                    for j,name in enumerate(summary['names']):writer.writerow([task,profile,f'{t:.8f}',name,f'{data["force_N"][i,j]:.6f}',f'{data["active_force_N"][i,j]:.6f}',f'{data["passive_force_N"][i,j]:.6f}','sampled_draft' if task=='jump' else 'operator_fixture'])
                rows.append(f'<tr><td>{task}</td><td>{html.escape(profile)}</td><td>{summary["samples"]}</td><td>{len(checks["scaled_elements"])}</td><td>{checks["moment_balance_max_error"]:.2e}</td><td>{checks["GH_max_angle_deg"]:.3f}°</td><td>Pass</td></tr>')
    (OUT/'manifest.json').write_text(json.dumps({'configuration':cfg,'cases':manifest},indent=2),encoding='utf-8')
    page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Standard-model tension reference</title><style>*{box-sizing:border-box}body{margin:0;background:#0d1725;color:#e8eff8;font:16px/1.65 system-ui,sans-serif}main{max-width:1130px;margin:30px auto;padding:0 24px 70px}h1{font-size:31px;line-height:1.2}h2{font-size:22px;margin-top:30px}a{color:#91dcd6}.box{padding:16px 22px;border-left:4px solid #94d2be;background:#1b2e40;margin:22px 0}.draft{border-color:#e1ae84}code{font-size:14px;color:#b9d9ed}table{border-collapse:collapse;width:100%;font-size:14px}td,th{text-align:left;border-bottom:1px solid #364a60;padding:11px 10px}.scroll{overflow-x:auto}.grid{display:grid;grid-template-columns:1fr 1fr;gap:28px}small{color:#a5bbcf}@media(max-width:760px){.grid{display:block}.scroll table{min-width:850px}}</style><main><a href="../jump_validation/overview.html">← Model lab</a><h1>Standard-model muscle tension</h1><p>One declared mechanical solution for a prescribed movement. Standard anthropometry and muscle parameters are intentional inputs. Personal measurements, neural fatigue, tissue deformation and metabolic-energy optimization are outside the current task.</p><div class="box"><strong>Implemented:</strong> unbounded required tension, imported active/passive muscle law, optional GH reaction-direction stability, magnitude/continuity regularization, and independent reference-force multipliers for a selected muscle element or group.</div><div class="grid"><section><h2>Hard mechanical conditions</h2><ul><li>Muscle moments match the prescribed net demands.</li><li>Total tension equals passive tension plus nonnegative active tension.</li><li>No hard maximum strength or activation ceiling.</li><li>Active force is unavailable where native FLV gain is zero.</li><li>The shoulder reaction lies in the specified generic GH cone, here 20° with 16 inscribed faces.</li></ul></section><section><h2>How one history is selected</h2><p>Regularize normalized tension magnitude and changes over time:</p><p><code>J = ∫ ||F / Fref||² dt + 0.01 ∫ ||d(F / Fref)/dt||² dt</code></p><p>This chooses a reproducible solution. It is not a claim that a person minimizes this objective. The magnitude term prevents arbitrary constant self-stress; continuity discourages allocation changes between frames. Stability constraints can require antagonistic muscle tension.</p></section></div><h2>Why mechanical energy alone is insufficient</h2><p>At a held posture, mechanical power is zero even with high muscle tension. At the same joint velocity and net torque, different agonist–antagonist combinations also have the same signed net mechanical power. A mechanical-energy minimum alone therefore does not identify co-contraction. Minimum metabolic energy would require a further physiological model and remains deferred.</p><h2>Computed checks</h2><div class="scroll"><table><thead><tr><th>Fixture</th><th>Parameter profile</th><th>Samples</th><th>Changed elements</th><th>Balance residual</th><th>Max GH angle</th><th>Numerics</th></tr></thead><tbody>__ROWS__</tbody></table></div><p><small>Moment balance is in the source generalized-coordinate units; jump independent coordinates are rotational Nm. GH compression/force direction are internal constraints, not primary video output. Sampled solutions do not establish unsampled peaks.</small></p><div class="box draft"><strong>Jump is a draft fixture.</strong> It still contains the previously identified motion transients, LAT1 operating-length mapping issue and missing thoracoscapular muscle paths. The solver is functioning; the jump motion/model integration still needs repair before a finished muscle-tension video. OHP is reused only as an existing operator verification fixture.</div><h2>Individual parameter changes</h2><p>The examples change the quadriceps group by +10%, or only the right soleus element by +10%. The multiplier scales its reference force, active gain and imported passive force. This is a force-parameter / PCSA sensitivity under fixed specific-tension assumptions. Body mass, inertia, bone dimensions and render geometry stay fixed. Independent anatomical length, breadth and muscle-volume controls are a later extension.</p><h2>Download or inspect</h2><p><a href="jump/muscle_tensions.csv">Jump sampled tensions CSV</a> · <a href="jump/summary.json">Jump checks</a> · <a href="ohp/summary.json">OHP operator checks</a> · <a href="solver_checks.json">Independent mechanics fixtures</a> · <a href="../../scenarios/tension_reference.json">Configuration and profiles</a></p><p><a href="../jump_validation/muscle_assumptions.html">Agreed scope and model assumptions</a></p><h2>Method references</h2><p><a href="https://opensimconfluence.atlassian.net/wiki/spaces/OpenSim/pages/53089619/How%2BStatic%2BOptimization%2BWorks">Force allocation under prescribed movement</a> · <a href="https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0295003">GH stability constraints and muscle redundancy</a></p><small>The project uses an unbounded demand coefficient and a declared numerical reference rule. This differs from a bounded physiological activation or minimum-metabolic-energy simulation.</small></main></html>'''
    page=page.replace('<h2>Individual parameter changes</h2>','<h2>Dense visualization reference</h2><p><a href="../tension_visualization/index.html">Open the synchronized anatomy / mechanical proxy viewer</a>. Its 83 display-time samples use a causal magnitude-and-previous-tension regularizer with the same moment, passive/active and GH constraints. This streaming numerical selection differs from the batch temporal minimizer used by the 25-sample fixtures. Both displayed rigs share one identical dense record; neither computes forces from its rendered shape.</p><h2>Individual parameter changes</h2>')
    (OUT/'method.html').write_text(page.replace('__ROWS__',''.join(rows)),encoding='utf-8');print('TENSION_METHOD_REPORT',OUT/'method.html')

if __name__=='__main__':main()
